import csv, hashlib, json, subprocess, sys, tempfile
from pathlib import Path
from io import StringIO
site = Path('products/sites/shopify-catalogue-example')
dossier = Path('products/services/stream-commerce-catalogue')
result = dossier / 'barcode-entrypoint-rerun.json'
draft = dossier / 'operator-draft.md'
report = {'scope': 'Fictional offline fixtures', 'draft_sha256': hashlib.sha256(draft.read_bytes()).hexdigest(), 'verified': False}
def parse(path):
    reader = csv.DictReader(StringIO(path.read_text(encoding='utf-8-sig'), newline=''))
    return set(reader.fieldnames or []), list(reader)
def run(args):
    completed = subprocess.run(args, capture_output=True, text=True, timeout=15)
    try:
        output = json.loads(completed.stdout)
    except json.JSONDecodeError:
        output = completed.stdout
    return {'argv': args, 'exit': completed.returncode, 'output': output, 'stderr': completed.stderr}
try:
    entry = next(iter(sorted(site.rglob('verify_example.py'))))
    tables = {p: parse(p) for p in sorted(site.rglob('*.csv')) if p.is_file()}
    variants = [p for p, (columns, rows) in tables.items() if {'style_id','sku','barcode','price','color','size'} <= columns and rows]
    images = [p for p, (columns, rows) in tables.items() if {'style_id','color','position','url'} <= columns and rows]
    outputs = [p for p, (columns, rows) in tables.items() if {'Handle','Variant SKU','Variant Barcode'} <= columns and rows]
    report['discovery'] = {key: [str(p) for p in paths] for key, paths in [('variants', variants), ('images', images), ('outputs', outputs)]}
    baseline = None
    for variant in variants:
        for image in images:
            for output in outputs:
                attempt = run([sys.executable, str(entry), str(variant), str(image), str(output)])
                if attempt['exit'] == 0:
                    baseline = attempt
                    break
            if baseline is not None:
                break
        if baseline is not None:
            break
    if baseline is None:
        raise ValueError('No single-output fixture combination passed. Read the documented fixture paths before changing the offer.')
    report['baseline'] = baseline
    report['hashes'] = {str(p): hashlib.sha256(p.read_bytes()).hexdigest() for p in (entry, variant, image, output)}
    with tempfile.TemporaryDirectory() as scratch:
        modified = Path(scratch) / output.name
        reader = csv.DictReader(StringIO(output.read_text(encoding='utf-8'), newline=''))
        rows = list(reader)
        index = next(i for i, row in enumerate(rows) if row['Variant SKU'] and row['Variant Barcode'])
        original = rows[index]['Variant Barcode']
        last = original[-1]
        replacement = original[:-1] + ('1' if last == '0' else '0')
        rows[index]['Variant Barcode'] = replacement
        with modified.open('w', encoding='utf-8', newline='') as handle:
            writer = csv.DictWriter(handle, fieldnames=reader.fieldnames, lineterminator='\n')
            writer.writeheader()
            writer.writerows(rows)
        before = tables[output][1]
        after = parse(modified)[1]
        assert len(before) == len(after)
        changes = [(i, k) for i, (left, right) in enumerate(zip(before, after)) for k in left if left[k] != right[k]]
        assert changes == [(index, 'Variant Barcode')], changes
        report['mutation'] = {'data_row': index + 1, 'field': 'Variant Barcode', 'sku': rows[index]['Variant SKU'], 'before': original, 'after': replacement, 'sha256': hashlib.sha256(modified.read_bytes()).hexdigest()}
        negative = run([*baseline['argv'][:-1], str(modified)])
        report['negative'] = negative
        report['verified'] = negative['exit'] == 1 and negative['output'].get('failed') == ['identifiers_preserved_sku_barcode_color_size_price'] if isinstance(negative['output'], dict) else False
        if report['verified']:
            report['interpretation'] = 'Verifier flags one grouped preservation check. Locating the affected field and row in a supplied file requires manual comparison.'
except (StopIteration, ValueError, AssertionError, subprocess.TimeoutExpired) as error:
    report['error'] = f'{type(error).__name__}: {error}'
result.parent.mkdir(parents=True, exist_ok=True)
result.write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')
print(result.read_text(encoding='utf-8'))
